#!/usr/bin/env python3
"""Offline IPv6 target planner and replay evidence reconciler.

This tool implements the synthetic-evidence contract of the task statement:

* ``plan``    builds the deterministic probe schedule for a manifest.
* ``replay``  ingests a recorded ICMPv6 response log, quarantines malformed
               rows and reconciles the surviving evidence into segments.

Everything is computed offline from the supplied files.  No packets are sent,
no sockets are opened, no external service is contacted and no persistent
state is kept between invocations.  The words "internal" and "external" used
by the output describe *observable response evidence* only; they never assert
a firewall policy, a physical device or service reachability.
"""

from __future__ import annotations

import hashlib
import ipaddress
import json
import math
import os
import re
import stat
import sys
import traceback

PROG = "ipv6_replay"

# ---------------------------------------------------------------------------
# limits
# ---------------------------------------------------------------------------

MANIFEST_LIMIT = 1 << 20                 # 1 MiB
LOG_LIMIT = 96 * (1 << 20)               # 96 MiB
LOG_LINE_LIMIT = 300000                  # physical lines
LOG_LINE_BYTES = 4096                    # bytes per physical line, LF included
MAX_SELECTED = 2048                      # selected /64s summed over all windows

MAX_WINDOWS = 8
MAX_SCOPES = 32
MAX_LOW_COUNT = 32
MAX_ATTEMPTS = 3
MAX_SPACING = 1000
MAX_TIMEOUT = 1000000
MAX_START_MS = 10 ** 12
MAX_SEED = (1 << 64) - 1

ROW_KEYS = frozenset(
    ("probe_id", "received_ms", "target", "source", "type", "code")
)

ID_RE = re.compile(r"[A-Za-z][A-Za-z0-9_-]{0,31}")

DB8_SHIFT = 96
DB8_PREFIX = 0x20010DB8


class UserError(Exception):
    """Fatal, user visible error: exit status 2 with a stderr diagnostic."""


# ---------------------------------------------------------------------------
# small helpers
# ---------------------------------------------------------------------------


def is_int(value):
    """True for JSON integers (booleans and floats are excluded)."""
    return isinstance(value, int) and not isinstance(value, bool)


def fmt_addr(value):
    """Canonical textual form of a 128 bit address."""
    return str(ipaddress.IPv6Address(value))


def derive_canaries(seed, window_id, scope_id, network_text):
    """Derive the two canary IIDs for one (window, scope, /64) triple."""
    payload = "ipv6-evidence-v1\n%d\n%s\n%s\n%s\n" % (
        seed,
        window_id,
        scope_id,
        network_text,
    )
    digest = hashlib.sha256(payload.encode("ascii")).digest()
    c0 = int.from_bytes(digest[:8], "big") | (1 << 63)
    return c0, c0 ^ 1


# ---------------------------------------------------------------------------
# strict JSON parsing
# ---------------------------------------------------------------------------


def _reject_constant(name):
    raise ValueError("nonfinite JSON number: %s" % (name,))


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON object key: %r" % (key,))
        result[key] = value
    return result


def _parse_float(text):
    value = float(text)
    if not math.isfinite(value):
        raise ValueError("nonfinite JSON number")
    return value


def loads_strict(raw):
    """Parse UTF-8 JSON, rejecting BOMs, duplicate keys and nonfinite numbers."""
    text = raw.decode("utf-8")
    return json.loads(
        text,
        object_pairs_hook=_unique_object,
        parse_constant=_reject_constant,
        parse_float=_parse_float,
    )


# ---------------------------------------------------------------------------
# IPv6 helpers
# ---------------------------------------------------------------------------

_ADDR_CACHE = {}
_ADDR_CACHE_LIMIT = 200000


def _parse_ipv6_uncached(text):
    if "%" in text:
        return None
    for ch in text:
        if ch.isspace():
            return None
    try:
        value = int(ipaddress.IPv6Address(text))
    except ValueError:
        return None
    if value >> DB8_SHIFT != DB8_PREFIX:
        return None
    return value


def parse_ipv6(text):
    """Return the 128 bit value of a usable address, or None.

    An address is usable when it is a plain IPv6 address (no zone identifier,
    no whitespace) that lies inside 2001:db8::/32.
    """
    if not isinstance(text, str):
        return None
    cached = _ADDR_CACHE.get(text)
    if cached is not None:
        return cached if cached >= 0 else None
    value = _parse_ipv6_uncached(text)
    if value is None:
        value = -1
    if len(_ADDR_CACHE) >= _ADDR_CACHE_LIMIT:
        _ADDR_CACHE.clear()
    _ADDR_CACHE[text] = value
    return value if value >= 0 else None


# ---------------------------------------------------------------------------
# manifest validation
# ---------------------------------------------------------------------------


def _check_keys(obj, keys, where):
    if not isinstance(obj, dict):
        raise UserError("%s must be a JSON object" % where)
    present = set(obj)
    expected = set(keys)
    if present != expected:
        missing = sorted(expected - present)
        extra = sorted(present - expected)
        raise UserError(
            "%s must have exactly the keys %s (missing=%s unexpected=%s)"
            % (where, sorted(expected), missing, extra)
        )


def _check_id(value, where):
    if not isinstance(value, str):
        raise UserError("%s must be a string" % where)
    if ID_RE.fullmatch(value) is None:
        raise UserError("%s must match [A-Za-z][A-Za-z0-9_-]{0,31}" % where)
    return value


def _parse_prefix(text, where):
    """Validate an IPv6 CIDR prefix and return (network_int, prefix_len)."""
    if not isinstance(text, str):
        raise UserError("%s must be a string" % where)
    if "%" in text:
        raise UserError("%s must not contain a zone identifier" % where)
    for ch in text:
        if ch.isspace():
            raise UserError("%s must not contain whitespace" % where)
    if text.count("/") != 1:
        raise UserError("%s must be an IPv6 CIDR string with an explicit slash" % where)
    addr_part, _, len_part = text.partition("/")
    if not len_part or not all("0" <= ch <= "9" for ch in len_part):
        raise UserError("%s must carry a decimal prefix length" % where)
    prefix_len = int(len_part)
    if prefix_len not in (56, 64):
        raise UserError("%s must use prefix length /56 or /64" % where)
    if not addr_part:
        raise UserError("%s is missing an address part" % where)
    try:
        network = ipaddress.IPv6Network(addr_part + "/" + str(prefix_len), strict=True)
    except ValueError:
        raise UserError("%s is not a valid IPv6 CIDR prefix" % where)
    base = int(network.network_address)
    if base >> DB8_SHIFT != DB8_PREFIX:
        raise UserError("%s must lie wholly within 2001:db8::/32" % where)
    return base, prefix_len


def validate_manifest(obj):
    """Validate a decoded manifest and return the normalised manifest."""
    _check_keys(
        obj,
        ("version", "seed", "low_count", "attempts", "spacing_ms", "timeout_ms", "windows"),
        "manifest",
    )

    if not is_int(obj["version"]) or obj["version"] != 1:
        raise UserError("manifest version must be the integer 1")

    seed = obj["seed"]
    if not is_int(seed) or not (0 <= seed <= MAX_SEED):
        raise UserError("manifest seed must be an integer in [0, 2**64-1]")

    low_count = obj["low_count"]
    if not is_int(low_count) or not (1 <= low_count <= MAX_LOW_COUNT):
        raise UserError("manifest low_count must be an integer in [1, %d]" % MAX_LOW_COUNT)

    attempts = obj["attempts"]
    if not is_int(attempts) or not (1 <= attempts <= MAX_ATTEMPTS):
        raise UserError("manifest attempts must be an integer in [1, %d]" % MAX_ATTEMPTS)

    spacing_ms = obj["spacing_ms"]
    if not is_int(spacing_ms) or not (1 <= spacing_ms <= MAX_SPACING):
        raise UserError("manifest spacing_ms must be an integer in [1, %d]" % MAX_SPACING)

    timeout_ms = obj["timeout_ms"]
    if not is_int(timeout_ms) or not (1 <= timeout_ms <= MAX_TIMEOUT):
        raise UserError("manifest timeout_ms must be an integer in [1, %d]" % MAX_TIMEOUT)

    windows = obj["windows"]
    if not isinstance(windows, list):
        raise UserError("manifest windows must be an array")
    if len(windows) > MAX_WINDOWS:
        raise UserError("manifest windows must hold at most %d entries" % MAX_WINDOWS)

    seen_window_ids = set()
    normalised_windows = []
    total_selected = 0

    for window in windows:
        _check_keys(window, ("id", "start_ms", "scopes"), "window")
        window_id = _check_id(window["id"], "window id")
        if window_id in seen_window_ids:
            raise UserError("duplicate window id: %r" % (window_id,))
        seen_window_ids.add(window_id)

        start_ms = window["start_ms"]
        if not is_int(start_ms) or not (0 <= start_ms <= MAX_START_MS):
            raise UserError("window start_ms must be an integer in [0, %d]" % MAX_START_MS)

        scopes = window["scopes"]
        if not isinstance(scopes, list):
            raise UserError("window scopes must be an array")
        if len(scopes) > MAX_SCOPES:
            raise UserError("window scopes must hold at most %d entries" % MAX_SCOPES)

        seen_scope_ids = set()
        normalised_scopes = []
        window_bases = []

        for scope in scopes:
            _check_keys(scope, ("id", "prefix", "subnets"), "scope")
            scope_id = _check_id(scope["id"], "scope id")
            if scope_id in seen_scope_ids:
                raise UserError(
                    "duplicate scope id %r inside window %r" % (scope_id, window_id)
                )
            seen_scope_ids.add(scope_id)

            base, prefix_len = _parse_prefix(
                scope["prefix"], "scope %r prefix" % (scope_id,)
            )

            subnets = scope["subnets"]
            if not isinstance(subnets, list):
                raise UserError("scope subnets must be an array")
            for value in subnets:
                if not is_int(value):
                    raise UserError("scope subnets must contain integers only")
            if len(set(subnets)) != len(subnets):
                raise UserError("scope subnets must be distinct")

            if prefix_len == 64:
                if subnets != [0]:
                    raise UserError("a /64 scope must select exactly subnet [0]")
                bases = [base]
            else:
                if not (1 <= len(subnets) <= 256):
                    raise UserError("a /56 scope must select 1..256 subnets")
                for value in subnets:
                    if not (0 <= value <= 255):
                        raise UserError("scope subnets must lie in [0, 255]")
                bases = [base + (value << 64) for value in subnets]

            for network_base in bases:
                if network_base in window_bases:
                    raise UserError(
                        "overlapping /64 selections inside window %r" % (window_id,)
                    )
                window_bases.append(network_base)

            total_selected += len(bases)
            normalised_scopes.append(
                {
                    "id": scope_id,
                    "prefix": scope["prefix"],
                    "prefix_len": prefix_len,
                    "base": base,
                    "subnets": sorted(subnets),
                }
            )

        normalised_windows.append(
            {
                "id": window_id,
                "start_ms": start_ms,
                "scopes": sorted(normalised_scopes, key=lambda item: item["id"]),
            }
        )

    if total_selected > MAX_SELECTED:
        raise UserError(
            "manifest selects %d /64 networks, at most %d are allowed"
            % (total_selected, MAX_SELECTED)
        )

    return {
        "version": 1,
        "seed": seed,
        "low_count": low_count,
        "attempts": attempts,
        "spacing_ms": spacing_ms,
        "timeout_ms": timeout_ms,
        "windows": sorted(normalised_windows, key=lambda item: item["id"]),
    }


def load_manifest(path):
    raw = read_regular_file(path, MANIFEST_LIMIT, "manifest")
    try:
        obj = loads_strict(raw)
    except ValueError as exc:
        raise UserError("manifest is not valid JSON: %s" % (exc,))
    return validate_manifest(obj)


def read_regular_file(path, limit, label):
    try:
        info = os.stat(path)
    except OSError as exc:
        raise UserError("cannot read %s %r: %s" % (label, path, exc))
    if not stat.S_ISREG(info.st_mode):
        raise UserError("%s %r is not a regular file" % (label, path))
    if info.st_size > limit:
        raise UserError(
            "%s %r is %d bytes, the limit is %d bytes"
            % (label, path, info.st_size, limit)
        )
    try:
        with open(path, "rb") as handle:
            data = handle.read(limit + 1)
    except OSError as exc:
        raise UserError("cannot read %s %r: %s" % (label, path, exc))
    if len(data) > limit:
        raise UserError("%s %r exceeds the %d byte limit" % (label, path, limit))
    return data


# ---------------------------------------------------------------------------
# planning
# ---------------------------------------------------------------------------


class Segment(object):
    """One selected (window, scope, subnet) /64 and its scheduled targets."""

    __slots__ = ("window", "scope", "subnet", "base", "start_ms", "targets")

    def __init__(self, window, scope, subnet, base, start_ms, targets):
        self.window = window
        self.scope = scope
        self.subnet = subnet
        self.base = base
        self.start_ms = start_ms
        self.targets = targets


def build_segments(manifest):
    """Build the ordered list of segments and their scheduled targets."""
    seed = manifest["seed"]
    low_count = manifest["low_count"]
    segments = []
    for window in manifest["windows"]:
        start_ms = window["start_ms"]
        for scope in window["scopes"]:
            prefix_len = scope["prefix_len"]
            for subnet in scope["subnets"]:
                if prefix_len == 56:
                    base = scope["base"] + (subnet << 64)
                else:
                    base = scope["base"]
                network_text = fmt_addr(base) + "/64"
                c0, c1 = derive_canaries(
                    seed, window["id"], scope["id"], network_text
                )
                targets = [("low", index, index) for index in range(1, low_count + 1)]
                targets.append(("canary", 0, c0))
                targets.append(("canary", 1, c1))
                segments.append(
                    Segment(window["id"], scope["id"], subnet, base, start_ms, targets)
                )
    return segments


def iter_probes(manifest, segments):
    """Yield the scheduled probes in canonical order.

    Each item is a tuple:
        (probe_id, window, scope, subnet, target_int, role, slot, attempt,
         sent_ms, deadline_ms, segment_index)
    """
    attempts = manifest["attempts"]
    spacing_ms = manifest["spacing_ms"]
    timeout_ms = manifest["timeout_ms"]
    ordinals = {}
    for index, segment in enumerate(segments):
        ordinal = ordinals.get(segment.window, 0)
        sent_base = segment.start_ms + ordinal * spacing_ms
        for role, slot, iid in segment.targets:
            target = segment.base | iid
            for attempt in range(attempts):
                sent_ms = sent_base
                deadline_ms = sent_ms + timeout_ms
                yield (
                    "%s/%s/%d/%s-%d/%d"
                    % (segment.window, segment.scope, segment.subnet, role, slot, attempt),
                    segment.window,
                    segment.scope,
                    segment.subnet,
                    target,
                    role,
                    slot,
                    attempt,
                    sent_ms,
                    deadline_ms,
                    index,
                )
                sent_base += spacing_ms
                ordinal += 1
        ordinals[segment.window] = ordinal


def run_plan(path):
    manifest = load_manifest(path)
    segments = build_segments(manifest)
    probes = []
    for record in iter_probes(manifest, segments):
        (
            probe_id,
            window,
            scope,
            subnet,
            target,
            role,
            slot,
            attempt,
            sent_ms,
            deadline_ms,
            _index,
        ) = record
        probes.append(
            {
                "id": probe_id,
                "window": window,
                "scope": scope,
                "subnet": subnet,
                "target": fmt_addr(target),
                "role": role,
                "slot": slot,
                "attempt": attempt,
                "sent_ms": sent_ms,
                "deadline_ms": deadline_ms,
            }
        )
    return {"version": 1, "probes": probes}


# ---------------------------------------------------------------------------
# replay
# ---------------------------------------------------------------------------


class SegmentEvidence(object):
    """Accumulated evidence for one segment."""

    __slots__ = ("internal", "external", "hits", "targets")

    def __init__(self, low_count):
        self.internal = set()
        self.external = set()
        self.hits = set()
        self.targets = [
            {
                "iid": iid,
                "internal_attempts": set(),
                "external_attempts": set(),
                "external_sources": set(),
                "responded": set(),
            }
            for iid in range(1, low_count + 1)
        ]


def run_replay(manifest_path, responses_path):
    manifest = load_manifest(manifest_path)
    segments = build_segments(manifest)

    index = {}
    for record in iter_probes(manifest, segments):
        (
            probe_id,
            _window,
            _scope,
            _subnet,
            target,
            role,
            slot,
            attempt,
            sent_ms,
            deadline_ms,
            seg_index,
        ) = record
        index[probe_id] = (seg_index, target, role, slot, attempt, sent_ms, deadline_ms)

    low_count = manifest["low_count"]
    attempts = manifest["attempts"]
    evidence = [SegmentEvidence(low_count) for _ in segments]

    diagnostics = []
    accepted_rows = 0
    duplicate_rows = 0
    seen = set()

    try:
        info = os.stat(responses_path)
    except OSError as exc:
        raise UserError("cannot read responses %r: %s" % (responses_path, exc))
    if not stat.S_ISREG(info.st_mode):
        raise UserError("responses %r is not a regular file" % (responses_path,))
    if info.st_size > LOG_LIMIT:
        raise UserError(
            "responses %r is %d bytes, the limit is %d bytes"
            % (responses_path, info.st_size, LOG_LIMIT)
        )

    append_diagnostic = diagnostics.append
    try:
        handle = open(responses_path, "rb")
    except OSError as exc:
        raise UserError("cannot read responses %r: %s" % (responses_path, exc))

    with handle:
        lineno = 0
        for raw in handle:
            lineno += 1
            if lineno > LOG_LINE_LIMIT:
                raise UserError(
                    "responses log holds more than %d physical lines" % LOG_LINE_LIMIT
                )
            if len(raw) > LOG_LINE_BYTES:
                raise UserError(
                    "physical line %d exceeds %d bytes" % (lineno, LOG_LINE_BYTES)
                )

            # 1. json
            try:
                row = loads_strict(raw)
            except ValueError:
                append_diagnostic({"line": lineno, "reason": "json"})
                continue

            # 2. schema
            if not isinstance(row, dict) or set(row) != ROW_KEYS:
                append_diagnostic({"line": lineno, "reason": "schema"})
                continue
            probe_id = row["probe_id"]
            target_text = row["target"]
            source_text = row["source"]
            received_ms = row["received_ms"]
            icmp_type = row["type"]
            icmp_code = row["code"]
            if not isinstance(probe_id, str):
                append_diagnostic({"line": lineno, "reason": "schema"})
                continue
            if not isinstance(target_text, str) or not isinstance(source_text, str):
                append_diagnostic({"line": lineno, "reason": "schema"})
                continue
            if not probe_id or len(probe_id) > 200:
                append_diagnostic({"line": lineno, "reason": "schema"})
                continue
            if not (is_int(received_ms) and is_int(icmp_type) and is_int(icmp_code)):
                append_diagnostic({"line": lineno, "reason": "schema"})
                continue

            # 3. address
            target_value = parse_ipv6(target_text)
            source_value = parse_ipv6(source_text)
            if target_value is None or source_value is None:
                append_diagnostic({"line": lineno, "reason": "address"})
                continue

            # 4. unknown_probe
            record = index.get(probe_id)
            if record is None:
                append_diagnostic({"line": lineno, "reason": "unknown_probe"})
                continue
            seg_index, planned_target, role, slot, attempt, sent_ms, deadline_ms = record

            # 5. target_mismatch
            if target_value != planned_target:
                append_diagnostic({"line": lineno, "reason": "target_mismatch"})
                continue

            # 6. time
            if not (sent_ms <= received_ms < deadline_ms):
                append_diagnostic({"line": lineno, "reason": "time"})
                continue

            # 7. icmp
            if not (
                (icmp_type == 129 and icmp_code == 0)
                or (icmp_type == 1 and 0 <= icmp_code <= 6)
            ):
                append_diagnostic({"line": lineno, "reason": "icmp"})
                continue

            key = (probe_id, received_ms, target_value, source_value, icmp_type, icmp_code)
            if key in seen:
                duplicate_rows += 1
                continue
            seen.add(key)
            accepted_rows += 1

            seg_evidence = evidence[seg_index]
            if role == "canary":
                if icmp_type == 129 and icmp_code == 0 and source_value == planned_target:
                    seg_evidence.hits.add(slot)
                continue

            target_state = seg_evidence.targets[slot - 1]
            target_state["responded"].add(attempt)
            if icmp_type == 129 and icmp_code == 0:
                if source_value == planned_target:
                    target_state["internal_attempts"].add(attempt)
                    seg_evidence.internal.add(planned_target)
            else:
                if source_value != planned_target:
                    target_state["external_attempts"].add(attempt)
                    target_state["external_sources"].add(source_value)
                    seg_evidence.external.add(source_value)

    out_segments = []
    for index_, segment in enumerate(segments):
        seg_evidence = evidence[index_]
        overlap = seg_evidence.internal & seg_evidence.external
        if len(seg_evidence.hits) == 2:
            state = "alias_suspect"
        elif overlap:
            state = "ambiguous"
        else:
            state = "usable"
        if state != "usable":
            exposure = "excluded"
        elif seg_evidence.internal:
            exposure = "observed_internal_reply"
        else:
            exposure = "inconclusive"

        targets = []
        for target_state in seg_evidence.targets:
            if state == "alias_suspect":
                classification = "alias_suspect"
            elif state == "ambiguous":
                classification = "ambiguous"
            else:
                has_internal = bool(target_state["internal_attempts"])
                has_external = bool(target_state["external_attempts"])
                if has_internal and has_external:
                    classification = "mixed"
                elif has_internal:
                    classification = "internal"
                elif has_external:
                    classification = "external"
                else:
                    classification = "unknown"
            silent = [
                attempt
                for attempt in range(attempts)
                if attempt not in target_state["responded"]
            ]
            targets.append(
                {
                    "address": fmt_addr(segment.base | target_state["iid"]),
                    "classification": classification,
                    "internal_attempts": sorted(target_state["internal_attempts"]),
                    "external_attempts": sorted(target_state["external_attempts"]),
                    "external_sources": [
                        fmt_addr(value)
                        for value in sorted(target_state["external_sources"])
                    ],
                    "silent_attempts": silent,
                }
            )

        out_segments.append(
            {
                "window": segment.window,
                "scope": segment.scope,
                "subnet": segment.subnet,
                "network": fmt_addr(segment.base) + "/64",
                "state": state,
                "exposure": exposure,
                "canary_hits": sorted(seg_evidence.hits),
                "internal": [fmt_addr(value) for value in sorted(seg_evidence.internal)],
                "external": [fmt_addr(value) for value in sorted(seg_evidence.external)],
                "overlap": [fmt_addr(value) for value in sorted(overlap)],
                "targets": targets,
            }
        )

    return {
        "version": 1,
        "accepted_rows": accepted_rows,
        "duplicate_rows": duplicate_rows,
        "diagnostics": diagnostics,
        "segments": out_segments,
    }


# ---------------------------------------------------------------------------
# command line
# ---------------------------------------------------------------------------


def parse_args(argv):
    for token in argv:
        if token == "-h" or token == "--help":
            raise UserError("help switches (-h/--help) are not supported")
    if not argv:
        raise UserError(
            "usage: %s plan MANIFEST.json | %s replay MANIFEST.json RESPONSES.jsonl"
            % (PROG, PROG)
        )
    command = argv[0]
    if command not in ("plan", "replay"):
        raise UserError("unknown command %r" % (command,))
    rest = list(argv[1:])
    if "--" in rest:
        position = rest.index("--")
        rest = rest[:position] + rest[position + 1:]
    needed = 1 if command == "plan" else 2
    if len(rest) != needed:
        raise UserError(
            "usage: %s %s %s"
            % (PROG, command, "MANIFEST.json" if needed == 1 else "MANIFEST.json RESPONSES.jsonl")
        )
    return command, rest


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    try:
        command, paths = parse_args(list(argv))
    except UserError as exc:
        sys.stderr.write("%s: error: %s\n" % (PROG, exc))
        return 2

    try:
        if command == "plan":
            result = run_plan(paths[0])
        else:
            result = run_replay(paths[0], paths[1])
